```python
import cyclopts

app = cyclopts.App(name="myservice", help="Manage the myservice process.")


@app.default
def status() -> None:
    """Show the current status of the service (runs when no subcommand is given)."""
    print("Service status: unknown")


@app.command
def start() -> None:
    """Start the service."""
    print("Starting service...")


@app.command
def stop() -> None:
    """Stop the service."""
    print("Stopping service...")


if __name__ == "__main__":
    app()
